CREATE TRIGGER RefComplianceList_Version_Create
	ON RefComplianceList
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RCL_PK, 'RCL'
	FROM inserted
GO
CREATE TRIGGER RefComplianceList_Version_Update
	ON RefComplianceList
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RCL_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
